// 18-tap FIR, TRANSPOSED direct form: one multiply + one add per stage, so the
// register-to-register critical path is independent of tap count -> high Fmax.
// Same transfer function as the direct form (equivalent up to a fixed latency).
module firr18_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg [23:0] a0, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, a13, a14, a15, a16, a17;
    always @(posedge clk) begin
        if (!rst_n) begin
            a0 <= 24'd0; a1 <= 24'd0; a2 <= 24'd0; a3 <= 24'd0; a4 <= 24'd0; a5 <= 24'd0; a6 <= 24'd0; a7 <= 24'd0; a8 <= 24'd0; a9 <= 24'd0; a10 <= 24'd0; a11 <= 24'd0; a12 <= 24'd0; a13 <= 24'd0; a14 <= 24'd0; a15 <= 24'd0; a16 <= 24'd0; a17 <= 24'd0; y <= 16'd0;
        end else begin
            a0 <= 8'd2 * x + 3 + 24'd1380;
            a1 <= a0 + 24'd1378;
            a2 <= a1 + 24'd1376;
            a3 <= a2 + 24'd1374;
            a4 <= a3 + 24'd1372;
            a5 <= a4 + 24'd1370;
            a6 <= a5 + 24'd1368;
            a7 <= a6 + 24'd1366;
            a8 <= a7 + 24'd1364;
            a9 <= a8 + 24'd1362;
            a10 <= a9 + 24'd1360;
            a11 <= a10 + 24'd1358;
            a12 <= a11 + 24'd1356;
            a13 <= a12 + 24'd1354;
            a14 <= a13 + 24'd1352;
            a15 <= a14 + 24'd1350;
            a16 <= a15 + 24'd1348;
            a17 <= a16 + 24'd1346;
            y <= a17[15:0];
        end
    end
endmodule
